"""Evaluation-only fixtures for the bridge, generated by code from the real proposition distribution.

Source: tests/fixtures/bridge_profile.json.gz, extracted read-only from reference run 20261025-100039
(tests/fixtures/extract_bridge_profile.py): its 63 complete A07 propositions (verbatim assertions with their doses,
arms, models and populations), 471 validated findings (contexts, quantities, constraints, limits, modality,
attribution; no spans), 28 papers, 20 thematic conflicts and 135 system-gap strings.

compact_package(120)  the 28 papers replicated to 120 (new record IDs, the papers' own tiers and contrary flags),
                      every real proposition re-anchored per replica as A07 would accept it (links to findings
                      that are not eligible for their role are dropped, as A07's link check would), real thematic
                      conflicts bound to the propositions using their findings with CONFLICTING roles and global
                      reconciliation issues carrying the real conflict text, one appraisal proposition per paper
                      with NOT_ESTABLISHED findings, one SYSTEM_GAP gap per real system-gap string per replica,
                      and coverage for every selected paper (as A07 must). Counts at 120 papers are reported by
                      describe() and in docs/bridge_validation.md.
oversized_package()   adversarial: the compact package with ten times the propositions and gaps, each carrying
                      long qualifiers; built to exceed every downstream window.
fixture_plan()        a deterministic plan and allocation ledger of the kind A08 must return (not A08 output).

Everything here is stamped evaluation-only (publication.stamp): no publication stage accepts it.
"""
from __future__ import annotations

import copy
import gzip
import json
import re
from collections import defaultdict
from functools import lru_cache
from pathlib import Path

from litreview import bridge, publication
from litreview.evidence import normalized_proposition, role_allowed, status_of
from litreview.synthesis_registry import fingerprint

PROFILE = Path(__file__).parent / "fixtures" / "bridge_profile.json.gz"
NOTICE = "Evaluation-only bridge fixture generated from reference run 20261025-100039; not a scientific synthesis."


@lru_cache(maxsize=1)
def profile() -> dict:
    with gzip.open(PROFILE, "rt", encoding="utf-8") as fh:
        return json.load(fh)


def _remap(value, mapping):
    if isinstance(value, str):
        return re.sub(r"\bR\d{4}\b", lambda m: mapping.get(m[0], m[0]), value)
    if isinstance(value, list):
        return [_remap(x, mapping) for x in value]
    if isinstance(value, dict):
        return {_remap(k, mapping): _remap(v, mapping) for k, v in value.items()}
    return value


def _independence(ids, record_of):
    ids = sorted(set(ids))
    return {"papers": len({record_of[f] for f in ids}), "independent_studies": None,
            "independent_datasets_or_cohorts": None, "distinct_explicit_studies": 0,
            "distinct_explicit_datasets_or_cohorts": 0, "known_study_ids": [], "known_cohort_ids": [],
            "known_dataset_ids": [], "identity_unknown_findings": ids,
            "basis": "global explicit identifiers only; distinct IDs do not establish independence"}


def _finish(raw: dict, pid: str, findings: dict, theme: str) -> dict:
    """A proposition exactly as RegistrySynthesisJob._science completes it."""
    p = normalized_proposition({**raw, "proposition_id": pid})
    linked = sorted({x["finding_id"] for x in p["evidence"]})
    record_of = {f: findings[f]["record_id"] for f in linked}
    p["citation_record_ids"] = sorted(set(record_of.values()))
    p["independence"] = _independence(linked, record_of)
    p["independent_source_count"] = None
    p["independent_studies"] = None
    p["papers"] = p["independence"]["papers"]
    p["constraints"] = [f"{f}: {c}" for f in linked for c in findings[f].get("constraints", [])]
    p["ceiling"] = {f: findings[f].get("disposition") for f in linked}
    p["context_qualifiers"] = {f: findings[f].get("context") for f in linked}
    p["evidence_qualifiers"] = {f: {k: findings[f].get(k) for k in ("direction", "polarity", "modality", "assertion_type",
                                                                     "attributed_to", "context_id", "plain_language_limit")}
                                for f in linked}
    p["primary_theme_id"] = theme
    p["reconciliation_issue_ids"] = []
    p["scientific_limitations"] = []
    return p


def compact_package(n_papers: int = 120) -> dict:
    """{"pkg", "findings", "corpus"} for n_papers, deterministic."""
    prof = profile()
    base = prof["corpus"]
    by_record = defaultdict(list)
    for f in prof["findings"]:
        by_record[f["record_id"]].append(f)
    corpus, findings = [], {}
    for i in range(n_papers):
        original = base[i % len(base)]
        cycle = i // len(base)
        mapping = {r["record_id"]: f"R{cycle * len(base) + j + 1:04d}" for j, r in enumerate(base)}
        rec = _remap(copy.deepcopy(original), mapping)
        rec["themes"] = [f"T{i % 8 + 1}"]
        corpus.append(rec)
        for old in by_record[original["record_id"]]:
            f = _remap(copy.deepcopy(old), mapping)
            f["primary_theme_id"] = rec["themes"][0]
            findings[f["finding_id"]] = f
    present = {r["record_id"] for r in corpus}
    theme_of = {r["record_id"]: r["themes"][0] for r in corpus}
    props, gaps, items, coverage, issues = [], [], {}, [], []
    group_n = defaultdict(int)

    def pid_for(theme):
        g = int(theme[1:])
        group_n[theme] += 1
        return f"GROUP_G{g:04d}.P{group_n[theme]}"
    cycles = (n_papers + len(base) - 1) // len(base)
    for cycle in range(cycles):
        mapping = {r["record_id"]: f"R{cycle * len(base) + j + 1:04d}" for j, r in enumerate(base)}
        conflicts = [_remap(copy.deepcopy(c), mapping) for c in prof["conflicts"]]
        for real in prof["propositions"]:
            r = _remap(copy.deepcopy(real), mapping)
            links = [{"finding_id": f, "role": "SUPPORTING"} for f in r.get("supporting_finding_ids") or []]
            links += [{"finding_id": f, "role": "CONFLICTING"} for f in r.get("conflicting_finding_ids") or []]
            links = [x for x in links if x["finding_id"] in findings and role_allowed(findings[x["finding_id"]], x["role"])]
            if not links:
                continue
            supported = {x["finding_id"] for x in links}
            # real thematic conflicts naming a finding this proposition rests on: the other findings they name
            # join as CONFLICTING evidence (when eligible) and the conflict becomes a mandatory source item
            sources = []
            for n, c in enumerate(conflicts, 1):
                named = set(c["conflict"].get("finding_ids") or [])
                if named & supported:
                    iid = f"M-CONFLICT-{cycle}-{n}"
                    sources.append(iid)
                    items[iid] = {"item": {"item_id": iid, "kind": "CONFLICT", "required_visibility": "NARRATIVE",
                                           "theme_record": c["theme"]}, "source": c["conflict"]}
                    for f in sorted(named - supported):
                        if f in findings and role_allowed(findings[f], "CONFLICTING"):
                            links.append({"finding_id": f, "role": "CONFLICTING"})
            theme = theme_of[links[0]["finding_id"].split(":")[0]]
            raw = {"type": "SOURCE_GROUNDED", "assertion": r["assertion"], "evidence": links,
                   "source_item_ids": sorted(set(sources)), "satisfies": sorted(set(sources)),
                   "prominence": r.get("prominence") or "NARRATIVE_SUPPORTING"}
            props.append(_finish(raw, pid_for(theme), findings, theme))
        for n, s in enumerate(prof["systems_missing"], 1):
            iid = f"M-GAP-{cycle}-{n}"
            items[iid] = {"item": {"item_id": iid, "kind": "SYSTEM_GAP", "system": s, "required_visibility": "NARRATIVE"}}
            gaps.append({"type": "SYSTEM_GAP", "statement": s, "source_item_ids": [iid], "established_by": [],
                         "satisfies": [iid], "gap_id": f"GROUP_G{9000 + cycle:04d}.K{n}", "citation_record_ids": []})
            coverage.append({"manifest_item_id": iid, "status": "SATISFIED", "satisfied_by": gaps[-1]["gap_id"],
                             "required_visibility": "NARRATIVE"})
    # one appraisal proposition per paper with NOT_ESTABLISHED findings (A06's own limit text as the appraisal)
    for rec in corpus:
        ne = [f for f in findings.values() if f["record_id"] == rec["record_id"] and status_of(f) == "NOT_ESTABLISHED"][:6]
        if ne:
            theme = theme_of[rec["record_id"]]
            raw = {"type": "CLAIM_APPRAISAL",
                   "assertion": f"{rec['record_id']} reported claims its own evidence does not establish ({len(ne)} findings).",
                   "evidence": [{"finding_id": f["finding_id"], "role": "SUBJECT_OF_APPRAISAL",
                                 "appraisal": {"statement": f.get("plain_language_limit") or "Not established by its evidence",
                                               "claim_source_record_id": rec["record_id"],
                                               "a06_rationale": f.get("plain_language_limit") or "DOES_NOT_ESTABLISH"}}
                                for f in ne],
                   "source_item_ids": [], "satisfies": [], "prominence": "NARRATIVE_SUPPORTING"}
            props.append(_finish(raw, pid_for(theme), findings, theme))
    # every selected paper is covered, as A07 must: by a proposition citing it, else by its first supporting finding
    for rec in corpus:
        rid = rec["record_id"]
        iid = f"PAPER:{rid}"
        items[iid] = {"item": {"item_id": iid, "kind": "SELECTED_PAPER", "record_id": rid,
                               "required_visibility": "NARRATIVE" if rec.get("tier") == "CORE" and rec.get("is_contrary_evidence")
                               else "CITED"}, "source": rec}
        by = next((p for p in props if rid in p["citation_record_ids"]), None)
        if by is None:
            usable = sorted((f for f in findings.values() if f["record_id"] == rid and status_of(f) == "SUPPORTING"),
                            key=lambda f: bridge._natural(f["finding_id"]))
            if usable:
                theme = theme_of[rid]
                raw = {"type": "SOURCE_GROUNDED", "assertion": usable[0].get("plain_language_limit") or usable[0]["finding_id"],
                       "evidence": [{"finding_id": usable[0]["finding_id"], "role": "SUPPORTING"}],
                       "source_item_ids": [], "satisfies": [iid], "prominence": "NARRATIVE_SUPPORTING"}
                by = _finish(raw, pid_for(theme), findings, theme)
                props.append(by)
            else:
                by = {"gap_id": f"GROUP_G9900.K{len(gaps) + 1}", "type": "INSUFFICIENT_EVIDENCE",
                      "statement": f"{rid} contributes no usable finding to this review.", "source_item_ids": [iid],
                      "established_by": [], "satisfies": [iid], "citation_record_ids": [rid]}
                gaps.append(by)
        coverage.append({"manifest_item_id": iid, "status": "SATISFIED",
                         "satisfied_by": by.get("proposition_id") or by.get("gap_id"),
                         "required_visibility": items[iid]["item"]["required_visibility"]})
    # global reconciliation: each real conflict whose findings are used by two or more propositions
    pmap = {p["proposition_id"]: p for p in props}
    for iid, unit in sorted(items.items()):
        if unit["item"]["kind"] != "CONFLICT":
            continue
        named = set(unit["source"].get("finding_ids") or [])
        related = sorted(p["proposition_id"] for p in props if named & {x["finding_id"] for x in p["evidence"]})
        anchors = sorted(f for f in named if f in findings and status_of(findings[f]) == "SUPPORTING")
        if len(related) >= 2 and anchors:
            issue = {"kind": "CONTRADICTION", "proposition_ids": related, "finding_ids": anchors,
                     "limitation": unit["source"]["description"]}
            issue["issue_id"] = "RC-" + fingerprint(issue)[:16]
            if issue["issue_id"] not in {i["issue_id"] for i in issues}:
                issues.append(issue)
                for pid in related:
                    pmap[pid]["reconciliation_issue_ids"].append(issue["issue_id"])
                    pmap[pid]["scientific_limitations"].append(issue["limitation"])
                    pmap[pid]["constraints"].append(f"Global reconciliation: {issue['limitation']}")
    for iid, unit in items.items():
        if unit["item"]["kind"] == "CONFLICT":
            coverage.append({"manifest_item_id": iid, "status": "SATISFIED",
                             "satisfied_by": next(p["proposition_id"] for p in props if iid in p["satisfies"]),
                             "required_visibility": "NARRATIVE"})
    framework = {"version": 1, "primary_themes": [{"theme_id": f"T{i}", "name": f"Fixture theme {i}"} for i in range(1, 9)]}
    head = next(p for p in props if p["prominence"] in ("HEADLINE", "NARRATIVE_PRIMARY"))
    pkg = {"agent_id": "A07-SYN", "status": "COMPLETE", "propositions": props, "knowledge_gaps": gaps,
           "reconciliation": issues, "source_items": items, "coverage_realization": coverage,
           "coverage_incomplete_item_ids": [], "findings_unaccounted": [], "theme_framework": framework,
           "groups": [{"group_id": t["theme_id"], "primary_theme_id": t["theme_id"],
                       "proposition_ids": [p["proposition_id"] for p in props if p["primary_theme_id"] == t["theme_id"]]}
                      for t in framework["primary_themes"]],
           "thesis_options": [{"option_id": "T1", "type": "ORGANIZING_THESIS", "text": NOTICE,
                               "title_draft": "Evaluation fixture title", "contribution_statement_draft": NOTICE,
                               "proposition_ids": [head["proposition_id"]]}],
           "researcher_decision": {"selected_thesis": "T1", "adopted_interpretations": ["PI1"]},
           "author_interpretations": [{"pi_id": "PI1", "id": "AI1", "type": "AUTHOR_INTERPRETATION", "kind": "FUTURE_DIRECTION",
                                       "statement": NOTICE, "what_it_goes_beyond": NOTICE,
                                       "premise_proposition_ids": [head["proposition_id"]]}],
           "global_independence": _independence(list(findings), {f: findings[f]["record_id"] for f in findings}),
           "registry_fingerprint": fingerprint({"corpus": corpus, "findings": findings}),
           "fixture_notice": NOTICE}
    pkg = publication.stamp(pkg, NOTICE, "bridge-fixture")
    return {"pkg": pkg, "findings": list(findings.values()), "corpus": corpus}


def oversized_package(factor: int = 10) -> dict:
    """The compact package with `factor` times the propositions and gaps (new IDs, same evidence), each
    proposition carrying every constraint of its theme: adversarial, for admission tests."""
    base = compact_package(120)
    pkg = copy.deepcopy(base["pkg"])
    props, gaps = [], []
    by_theme = defaultdict(list)
    for p in pkg["propositions"]:
        by_theme[p["primary_theme_id"]] += p["constraints"]
    for k in range(factor):
        for p in pkg["propositions"]:
            q = copy.deepcopy(p)
            q["proposition_id"] = f"{p['proposition_id']}.x{k}"
            q["constraints"] = list(dict.fromkeys(by_theme[p["primary_theme_id"]]))
            q["prominence"] = "HEADLINE" if k == 0 else q["prominence"]
            props.append(q)
        for g in pkg["knowledge_gaps"]:
            h = copy.deepcopy(g)
            h["gap_id"] = f"{g['gap_id']}.x{k}"
            gaps.append(h)
    pkg.update(propositions=props, knowledge_gaps=gaps, reconciliation=[], coverage_realization=[])
    head = props[0]["proposition_id"]
    pkg["thesis_options"][0]["proposition_ids"] = [head]
    pkg["author_interpretations"][0]["premise_proposition_ids"] = [head]
    return {**base, "pkg": pkg}


def fixture_plan(pkg: dict, corpus: list[dict], table: dict, group_size: int = 16) -> tuple[dict, list[dict]]:
    """A deterministic plan and ledger satisfying every bridge rule: an Introduction, one section per theme, a
    Conclusion. Mandatory and high-prominence propositions are DISCUSSED (or GROUPED_WITH in groups of
    group_size when a theme has many); NARRATIVE_SUPPORTING ones grouped; DISPLAY and SUPPLEMENTARY ones
    TABLE_ONLY when the table shows them, else NOT_INDIVIDUALLY_DISCUSSED with a reason; gaps grouped in the
    Conclusion; the adopted interpretation discussed last."""
    els = bridge.elements(pkg)
    mand = bridge.mandatory_reasons(pkg, corpus)
    shown = set(table.get("propositions_fully_shown") or [])
    themes = [t["theme_id"] for t in pkg["theme_framework"]["primary_themes"]]
    sections = [{"section_id": "S1", "heading": "Introduction", "theme_ids": [], "ordered_items": []}]
    sections += [{"section_id": f"S{i + 2}", "heading": f"Evidence for fixture theme {t[1:]}", "theme_ids": [t],
                  "ordered_items": []} for i, t in enumerate(themes)]
    concl = {"section_id": f"S{len(themes) + 2}", "heading": "Conclusion", "theme_ids": [], "ordered_items": []}
    sections.append(concl)
    ledger, groups = [], 0

    def place(section, ids, kind):
        nonlocal groups
        if len(ids) == 1:
            section["ordered_items"].append({"item_id": ids[0], "item_type": kind, "group": None, "note_to_writer": None})
            ledger.append({"item_id": ids[0], "outcome": "DISCUSSED", "section_id": section["section_id"],
                           "grouped_with": [], "reason": None})
            return
        groups += 1
        g = f"U{groups}"
        for i in ids:
            section["ordered_items"].append({"item_id": i, "item_type": kind, "group": g,
                                             "note_to_writer": "Discuss together; keep each member's own qualifications."})
            ledger.append({"item_id": i, "outcome": "GROUPED_WITH", "section_id": section["section_id"],
                           "grouped_with": [x for x in ids if x != i], "reason": None})

    def chunks(xs):
        out = [xs[i:i + group_size] for i in range(0, len(xs), group_size)]
        if len(out) > 1 and len(out[-1]) == 1:
            out[-2:] = [out[-2][:-1], out[-2][-1:] + out[-1]]
        return out
    for section, theme in zip(sections[1:-1], themes):
        ids = [e for e, el in els.items() if el["kind"] == "PROPOSITION" and el["record"]["primary_theme_id"] == theme]
        lead = [e for e in ids if els[e]["record"]["prominence"] in ("HEADLINE", "NARRATIVE_PRIMARY") and not mand[e]][:6]
        must = [e for e in ids if mand[e]]
        support = [e for e in ids if e not in lead and e not in must
                   and els[e]["record"]["prominence"] in ("HEADLINE", "NARRATIVE_PRIMARY", "NARRATIVE_SUPPORTING")]
        rest = [e for e in ids if e not in lead + must + support]
        for e in lead:
            place(section, [e], "PROPOSITION")
        for part in chunks(must):
            place(section, part, "PROPOSITION")
        for part in chunks(support):
            place(section, part, "PROPOSITION")
        for e in rest:
            ledger.append({"item_id": e, "outcome": "TABLE_ONLY" if e in shown else "NOT_INDIVIDUALLY_DISCUSSED",
                           "section_id": None, "grouped_with": [],
                           "reason": None if e in shown else "Display-level detail beyond the word budget's reach"})
    # propositions outside the approved themes (A07's administrative UNMAPPED bucket) and the knowledge gaps are
    # written, grouped, in bounded subsections before the Conclusion: a section is the unit admission subdivides
    # by, so a plan that put every gap in one section would be stopped before dispatch (as A08's would be)
    stray = [e for e, el in els.items() if el["kind"] == "PROPOSITION" and el["record"].get("primary_theme_id") not in themes]
    gap_ids = [e for e, el in els.items() if el["kind"] == "GAP"]
    units = [("PROPOSITION", part) for part in chunks(stray)] + [("GAP", part) for part in chunks(gap_ids)]
    parts = [units[i:i + 6] for i in range(0, len(units), 6)]
    gap_sections = []
    for k, part in enumerate(parts, 1):
        s = {"section_id": f"S{len(sections) + k}", "heading": f"Evidence gaps and limitations, part {k}",
             "theme_ids": [], "ordered_items": []}
        for kind, ids in part:
            place(s, ids, kind)
        gap_sections.append(s)
    sections[-1:-1] = gap_sections
    for e, el in els.items():
        if el["kind"] == "AUTHOR_INTERPRETATION":
            place(concl, [e], "AUTHOR_INTERPRETATION")
    budgets = {"S1": 600, concl["section_id"]: 500, **{s["section_id"]: 120 for s in gap_sections}}
    for s in sections:
        s.update(level=2 if s in gap_sections else 1, heading_kind="DESCRIPTIVE", heading_proposition_ids=[],
                 purpose=f"Fixture purpose of {s['heading']}",
                 word_budget=budgets.get(s["section_id"], (4750 - 1100) // len(themes)), display_item_ids=[],
                 transition_in="", transition_out="", wording_restrictions=[])
    sections[1]["display_item_ids"] = ["T1"] if table.get("status") == "BUILT" else []
    written = [e["item_id"] for e in ledger if e["outcome"] in ("DISCUSSED", "GROUPED_WITH")
               and els[e["item_id"]]["kind"] == "PROPOSITION" and not els[e["item_id"]]["record"].get("appraised_finding_ids")]
    plan = {"agent_id": "A08-OL", "prompt_version": "0.5", "status": "COMPLETE", "warnings": [], "limitations": [],
            "plan_version": "fixture-1",
            "title": {"text": "Evaluation fixture title", "word_count": 3, "proposition_ids": written[:1]},
            "abstract_plan": {"target_words": 200, "ordered_proposition_ids": written[:4], "contribution_statement": NOTICE},
            "keywords": ["disulfiram", "copper", "glioblastoma"],
            "writing_order": [s["section_id"] for s in sections[1:-1]] + ["S1", concl["section_id"]],
            "sections": sections,
            "display_items": [{"display_id": "T1", "type": "TABLE_COMPARISON", "placement_section_id": "S2",
                               "purpose": "Compare evidence across systems"}] if table.get("status") == "BUILT" else [],
            "budget_summary": {"main_text_words_planned": 4750, "main_text_limit": 5000},
            "readability": {"background_concepts": [], "abbreviations": [{"abbr": "DSF", "expansion": "disulfiram"},
                                                                           {"abbr": "GBM", "expansion": "glioblastoma"}],
                            "nomenclature": [{"entity": "copper diethyldithiocarbamate", "form_to_use": "CuET",
                                              "alternative_at_first_mention": "Cu(DDC)2"}]},
            "reserved_human_items": ["author_contributions", "ai_disclosure", "competing_interests"]}
    return plan, ledger


def tagged_text(packet: dict, words_per_unit: int = 0, max_citations: int | None = None) -> str:
    """Prose that passes the section gate, made only from the packet: one sentence per unit (a grouped passage is
    one sentence tagged with every member), citing the members' own papers (all of them, or the first
    max_citations: a writer that drops citations, which the contrary-evidence release gate must catch), stating
    only numbers in their records (here: none). Evaluation text."""
    limit = bridge.max_findings_per_sentence()
    records = bridge.packet_records(packet)
    out = ["This section is organized by evidence system. ⟦ORG⟧"]
    for u in packet["units"]:
        part = []                                # a passage: as many sentences as A10's per-sentence limit needs
        for i in u["item_ids"] + [None]:
            if i is not None and len(bridge.sentence_findings(part + [i], records)) <= limit:
                part.append(i)
                continue
            if part:
                cited = list(dict.fromkeys(c for x in part for c in packet["citations_by_tag"].get(x, [])))
                cited = cited[:max_citations] if max_citations is not None else cited
                cites = "; ".join(f"@{c}" for c in cited)
                out.append(f"Evaluation sentence for {'a group of elements' if len(part) > 1 else 'an element'}"
                           f"{' [' + cites + ']' if cites else ''}. ⟦{','.join(part)}⟧")
            part = [i] if i is not None else []
    return " ".join(out)


def describe(fx: dict) -> dict:
    pkg = fx["pkg"]
    mand = bridge.mandatory_reasons(pkg, fx["corpus"])
    return {"papers": len(fx["corpus"]), "findings": len(fx["findings"]), "propositions": len(pkg["propositions"]),
            "gaps": len(pkg["knowledge_gaps"]), "reconciliation_issues": len(pkg["reconciliation"]),
            "mandatory_elements": sum(1 for v in mand.values() if v),
            "conflicting_links": sum(len(p["conflicting_finding_ids"]) for p in pkg["propositions"])}


def bridge_stubs(run, monkeypatch, ps: dict | None = None):
    """For stage tests about A10/A11/A12 sequencing only: a minimal plan state, and the bridge's own checks
    (binding gate, stamps, staleness) switched off. Tests of those checks live in test_bridge.py."""
    ps = ps or {"pkg": {}, "findings": [], "corpus": [], "plan": {"sections": []}, "ledger": [], "packets": {},
                "amap": {}, "pv": "pv", "ev": "ev", "journal": {}, "table": None}
    monkeypatch.setattr(run, "_plan_state", lambda: ps)
    monkeypatch.setattr(run, "_binding_gate", lambda *a, **k: None)
    monkeypatch.setattr(run, "_stamp", lambda rv, m, ps: rv)
    monkeypatch.setattr(run, "_require_current", lambda *a, **k: None)
    monkeypatch.setattr(run, "_bridge_fingerprint", lambda *a, **k: "fp")
    return ps
